/* Source database for the legacy Contoso CU (Contoso_CU).
   Run in an EMPTY Azure SQL Database (or SQL Server 2016+) to create the operational source
   that Fabric mirrors. Every table has a primary key, which mirroring requires.
   Generated from data/contoso_cu/*.csv - regenerate if you change the CSVs. */
SET NOCOUNT ON;
GO

DROP TABLE IF EXISTS dbo.[dim_branch];
CREATE TABLE dbo.[dim_branch]
(
    [BranchId] VARCHAR(20) NOT NULL,
    [BranchName] VARCHAR(100) NULL,
    [Region] VARCHAR(20) NULL,
    [State] VARCHAR(2) NULL,
    CONSTRAINT [PK_dim_branch] PRIMARY KEY ([BranchId])
);
GO

