DROP TABLE IF EXISTS dbo.[glossary_kpi_definitions];
CREATE TABLE dbo.[glossary_kpi_definitions]
(
    [KPI] VARCHAR(50) NOT NULL,
    [Definition] VARCHAR(400) NULL,
    [Owner] VARCHAR(100) NULL,
    [Calculation] VARCHAR(400) NULL,
    CONSTRAINT [PK_glossary_kpi_definitions] PRIMARY KEY ([KPI])
);
GO

INSERT INTO dbo.[glossary_kpi_definitions] ([KPI], [Definition], [Owner], [Calculation]) VALUES
('LoansBooked', 'Count of new consumer and small-business loans funded in the month.', 'Retail Finance', 'SUM(FactMonthlyKPI[LoansBooked])'),
('DepositGrowthPct', 'Month-over-month percentage growth of total deposits.', 'Treasury Analytics', '(CurrentMonthDeposits-PriorMonthDeposits)/PriorMonthDeposits'),
('NPS', 'Net Promoter Score from post-interaction surveys.', 'Member Experience', 'Promoters% - Detractors%'),
('DelinquencyRatePct', 'Percent of loans 30+ days past due.', 'Credit Risk', 'DelinquentBalance/TotalLoanBalance'),
('DigitalAdoptionPct', 'Share of active members using digital channels in the month.', 'Digital Banking', 'DigitalActiveMembers/ActiveMembers');
GO

